1	import { vpsTerm, vpsTermPriceCents } from "./billing-terms";
2	import { extraDiskCentsAt } from "./extra-disk";
3	
4	/**
5	 * What one renewal costs — the SINGLE definition, used by every path that quotes
6	 * or charges one: the automatic sweep in worker/billing.ts, the saved-card path,
7	 * the "Renew now" button, the server page and the deploy wizard's term cards.
8	 *
9	 * WHY IT LIVES IN ITS OWN FILE. It used to sit in lib/stripe-cards.ts, which
10	 * imports the Stripe SDK and (transitively) nodemailer. The moment a CLIENT
11	 * component — the deploy wizard — needed the renewal price, that import chain
12	 * dragged `nodemailer/lib/dkim` into the browser bundle and the build failed with
13	 * "Can't resolve 'fs'". The pricing rule is pure arithmetic and has no business
14	 * carrying a mail transport with it, so it lives here with only the two tiny
15	 * modules it genuinely needs. lib/stripe-cards.ts re-exports it, so no server-side
16	 * caller had to change.
17	 *
18	 * The rule this file exists to enforce: there is ONE renewal formula. Two
19	 * incidents in one day came from a second copy — first a button that hardcoded
20	 * "+30 days" and the monthly price while the action charged a full term ($8.99
21	 * shown, $97.09 taken), then the shared quote written to fix it, which computed
22	 * from `plan.priceCents` and so ignored `gamePlan` and would have billed a $4.99
23	 * game server at its $8.99 base plan. Do not add a second formula.
24	 */
25	export type RenewalCharge = {
26	  months: number;
27	  totalCents: number;
28	  /** The extra-root-disk portion, which gets its own invoice line. */
29	  extraDiskCents: number;
30	  extraDiskMonthlyCents: number;
31	  /** Human label for the invoice / receipt ("Nebula VPS" or the game plan name). */
32	  label: string;
33	};
34	
35	export type PricedServer = {
36	  termMonths: number;
37	  extraDiskGB: number;
38	  plan: { name: string; priceCents: number };
39	  gamePlan: { name: string; priceCents: number; termMonths: number } | null;
40	  dedicatedIp: unknown | null;
41	};
42	
43	export function renewalCharge(
44	  server: PricedServer,
45	  prices: { ipMonthlyCents: number; extraDiskPerGbCents: number },
46	): RenewalCharge {
47	  const isGame = !!server.gamePlan;
48	  const months = isGame ? server.gamePlan!.termMonths : vpsTerm(server.termMonths).months;
49	  // Extra root disk is billed EVERY cycle at the current per-GB price. Game plans
50	  // are a flat all-in price and never carry the add-on lines.
51	  const extraDiskMonthlyCents = isGame ? 0 : extraDiskCentsAt(server.extraDiskGB, prices.extraDiskPerGbCents);
52	  const extraDiskCents = extraDiskMonthlyCents * months;
53	  const totalCents = isGame
54	    ? server.gamePlan!.priceCents
55	    : vpsTermPriceCents(server.plan.priceCents, months) +
56	      // Bill the IP surcharge only when the server ACTUALLY holds a dedicated IP,
57	      // not off the intent flag — a NAT-fallback server must never be charged for
58	      // an IP it never received.
59	      (server.dedicatedIp ? prices.ipMonthlyCents * months : 0) +
60	      extraDiskCents;
61	  return {
62	    months,
63	    totalCents,
64	    extraDiskCents,
65	    extraDiskMonthlyCents,
66	    label: isGame ? server.gamePlan!.name : `${server.plan.name} VPS`,
67	  };
68	}
