1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import { readFileSync } from "node:fs";
4	import { join } from "node:path";
5	import { DUNNING_RETRY_ATTEMPTS } from "../lib/mailer.ts";
6	import {
7	  CARD_EXPIRY_WARN_DAYS,
8	  CARD_SUSPEND_DAY,
9	  DUNNING_EXHAUSTED,
10	  LAST_RETRY_DAY,
11	  RETRY_DAYS,
12	  SUSPEND_SLIP_CAP_DAYS,
13	  dunningView,
14	} from "../lib/dunning-schedule.ts";
15	
16	/**
17	 * REAL RISK — the portal telling a customer something the worker will not do.
18	 *
19	 * `lib/dunning-schedule.ts` exists so the billing page can say where a customer is
20	 * in the dunning ladder and when their server would pause. It cannot import those
21	 * numbers from `worker/billing.ts` (that module drags Proxmox, nodemailer and the
22	 * job queue into a page bundle), so the day arithmetic is duplicated there.
23	 *
24	 * A duplicated schedule that drifts is worse than no schedule at all: the page
25	 * would promise "we'll try again on the 3rd, nothing pauses before the 6th" while
26	 * the worker suspends on the 4th. This file is the guard — it reads worker/billing.ts
27	 * and fails the moment the two stop agreeing, exactly as
28	 * `test/dunning-schedule.test.ts` guards the admin panel's hand-copied floor.
29	 *
30	 * Deterministic: source-text assertions and arithmetic on fixed dates. No clock,
31	 * no DB, no Stripe, no network.
32	 */
33	
34	const REPO = join(__dirname, "..");
35	/** Sources are read with whitespace collapsed, so reformatting is not a failure. */
36	const readNormalized = (rel: string) => readFileSync(join(REPO, rel), "utf8").replace(/\s+/g, " ");
37	const BILLING_SRC = readNormalized("worker/billing.ts");
38	const SCHEDULE_SRC = readNormalized("lib/dunning-schedule.ts");
39	
40	/* ---- the duplicated arithmetic still matches the worker ------------------ */
41	
42	test("the portal's retry-day formula is the worker's formula", () => {
43	  // worker/billing.ts: `const retryDayFor = (retry: number) => 2 * retry - 1;`
44	  const inWorker = /const retryDayFor = \(retry: number\) => (\d+) \* retry - (\d+);/.exec(BILLING_SRC);
45	  assert.ok(inWorker, "retryDayFor not found in worker/billing.ts — re-read the ladder");
46	  const inPortal = /export const retryDayFor = \(retry: number\) => (\d+) \* retry - (\d+);/.exec(SCHEDULE_SRC);
47	  assert.ok(inPortal, "retryDayFor not found in lib/dunning-schedule.ts");
48	  assert.equal(inPortal![1], inWorker![1], "retry-day multiplier drifted from the worker");
49	  assert.equal(inPortal![2], inWorker![2], "retry-day offset drifted from the worker");
50	});
51	
52	test("the portal's suspension and slip constants are the worker's", () => {
53	  const suspendOffset = /const CARD_SUSPEND_DAY = LAST_RETRY_DAY \+ (\d+);/.exec(BILLING_SRC);
54	  assert.ok(suspendOffset, "CARD_SUSPEND_DAY not found in worker/billing.ts");
55	  assert.equal(
56	    CARD_SUSPEND_DAY,
57	    LAST_RETRY_DAY + Number(suspendOffset![1]),
58	    "the portal would name a suspension day the worker does not honour",
59	  );
60	
61	  const slip = /const SUSPEND_SLIP_CAP_DAYS = (\d+);/.exec(BILLING_SRC);
62	  assert.ok(slip, "SUSPEND_SLIP_CAP_DAYS not found in worker/billing.ts");
63	  assert.equal(SUSPEND_SLIP_CAP_DAYS, Number(slip![1]), "the slip cap drifted from the worker");
64	
65	  const exhausted = /const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS \+ (\d+);/.exec(BILLING_SRC);
66	  assert.ok(exhausted, "DUNNING_EXHAUSTED not found in worker/billing.ts");
67	  assert.equal(DUNNING_EXHAUSTED, DUNNING_RETRY_ATTEMPTS + Number(exhausted![1]));
68	
69	  const warn = /const CARD_EXPIRY_WARN_DAYS = (\d+);/.exec(BILLING_SRC);
70	  assert.ok(warn, "CARD_EXPIRY_WARN_DAYS not found in worker/billing.ts");
71	  assert.equal(
72	    CARD_EXPIRY_WARN_DAYS,
73	    Number(warn![1]),
74	    "the page would flag a card as expiring on a different day than the email warns",
75	  );
76	});
77	
78	test("the retry-attempt count is IMPORTED, never re-declared in the portal copy", () => {
79	  // The one number the dunning emails subtract from. A second copy of it is how
80	  // "we'll try 2 more times" starts outliving the retries that back it.
81	  assert.ok(
82	    SCHEDULE_SRC.includes('import { DUNNING_RETRY_ATTEMPTS } from "./mailer";'),
83	    "lib/dunning-schedule.ts must import the attempt count, not restate it",
84	  );
85	  assert.doesNotMatch(
86	    SCHEDULE_SRC,
87	    /const DUNNING_RETRY_ATTEMPTS = \d/,
88	    "the attempt count must never be hardcoded beside the schedule derived from it",
89	  );
90	});
91	
92	test("the portal's ladder is still the documented day-1/3/5, pause-on-6 schedule", () => {
93	  assert.deepEqual(RETRY_DAYS, [1, 3, 5]);
94	  assert.equal(CARD_SUSPEND_DAY, 6);
95	  assert.equal(DUNNING_EXHAUSTED, 4, "the expiry-day attempt plus three retries");
96	});
97	
98	/* ---- the customer-facing view ------------------------------------------- */
99	
100	const EXPIRY = new Date("2026-07-01T00:00:00.000Z");
101	const DAY = 86_400_000;
102	const at = (days: number) => new Date(EXPIRY.getTime() + days * DAY);
103	const CFG = { graceDays: 3, autoSuspend: true, now: at(2) };
104	
105	test("no card: the ladder is not promised at all, and grace is the shorter clock", () => {
106	  const v = dunningView(
107	    { expiresAt: EXPIRY, dunningStage: 0, dunningNextAt: null },
108	    { ...CFG, hasCard: false },
109	  );
110	  // Promising "0 of 4 attempts" to someone whose card will never be tried is the
111	  // single most misleading thing this panel could say.
112	  assert.equal(v.attemptsTotal, 0);
113	  assert.equal(v.attemptsLeft, 0);
114	  assert.equal(v.inDunning, false);
115	  assert.equal(v.nextAttemptAt, null);
116	  assert.deepEqual(v.suspendAt, at(3), "no card means plain grace, not the card runway");
117	});
118	
119	test("card on file, nothing failed yet: the full runway, no decline claimed", () => {
120	  const v = dunningView(
121	    { expiresAt: EXPIRY, dunningStage: 0, dunningNextAt: null },
122	    { ...CFG, hasCard: true },
123	  );
124	  assert.equal(v.inDunning, false, "stage 0 means nothing has been declined");
125	  assert.equal(v.attemptsMade, 0);
126	  assert.equal(v.attemptsTotal, DUNNING_EXHAUSTED);
127	  assert.equal(v.attemptsLeft, DUNNING_EXHAUSTED);
128	  assert.equal(v.exhausted, false);
129	  assert.deepEqual(v.suspendAt, at(CARD_SUSPEND_DAY), "a card buys the longer runway");
130	});
131	
132	test("mid-ladder: attempts made and left add up to what the emails promise", () => {
133	  for (let stage = 1; stage <= DUNNING_EXHAUSTED; stage++) {
134	    const v = dunningView(
135	      { expiresAt: EXPIRY, dunningStage: stage, dunningNextAt: at(1) },
136	      { ...CFG, hasCard: true },
137	    );
138	    assert.equal(v.inDunning, true);
139	    assert.equal(v.attemptsMade, stage);
140	    assert.equal(v.attemptsMade + v.attemptsLeft, DUNNING_EXHAUSTED, `stage ${stage}`);
141	    assert.equal(v.exhausted, stage >= DUNNING_EXHAUSTED, `stage ${stage}`);
142	  }
143	});
144	
145	test("a stage past the end cannot show more attempts than the ladder has", () => {
146	  // Defensive: a hand-edited row must not render "attempt 9 of 4".
147	  const v = dunningView(
148	    { expiresAt: EXPIRY, dunningStage: 99, dunningNextAt: null },
149	    { ...CFG, hasCard: true },
150	  );
151	  assert.equal(v.attemptsMade, DUNNING_EXHAUSTED);
152	  assert.equal(v.attemptsLeft, 0);
153	  assert.equal(v.exhausted, true);
154	});
155	
156	test("a suspension date never lands before a retry we already promised", () => {
157	  // A late-starting sequence: the worker has emailed "we'll try again on day 8",
158	  // so the page must not tell the customer it pauses on day 6.
159	  const v = dunningView(
160	    { expiresAt: EXPIRY, dunningStage: 3, dunningNextAt: at(8) },
161	    { ...CFG, hasCard: true },
162	  );
163	  assert.deepEqual(v.suspendAt, at(8));
164	});
165	
166	test("…but the slip a promised retry can buy is capped", () => {
167	  // Otherwise a permanently failing Stripe would have the page promise a
168	  // suspension date that recedes forever.
169	  const v = dunningView(
170	    { expiresAt: EXPIRY, dunningStage: 3, dunningNextAt: at(90) },
171	    { ...CFG, hasCard: true },
172	  );
173	  assert.deepEqual(v.suspendAt, at(CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS));
174	});
175	
176	test("a retry scheduled before the calendar deadline does not pull suspension in", () => {
177	  const v = dunningView(
178	    { expiresAt: EXPIRY, dunningStage: 2, dunningNextAt: at(3) },
179	    { ...CFG, hasCard: true },
180	  );
181	  assert.deepEqual(v.suspendAt, at(CARD_SUSPEND_DAY));
182	});
183	
184	test("with auto-suspend off the page must not name a suspension date", () => {
185	  const v = dunningView(
186	    { expiresAt: EXPIRY, dunningStage: 2, dunningNextAt: at(3) },
187	    { ...CFG, hasCard: true, autoSuspend: false },
188	  );
189	  assert.equal(v.suspendAt, null, "the admin kill switch means nothing pauses on a timer");
190	});
191	
192	test("a long grace period wins over the card runway rather than shortening it", () => {
193	  // calendarSuspendDay is a max(): an operator who set a 30-day grace must not have
194	  // it silently cut to the 6-day card ladder.
195	  const v = dunningView(
196	    { expiresAt: EXPIRY, dunningStage: 0, dunningNextAt: null },
197	    { ...CFG, hasCard: true, graceDays: 30 },
198	  );
199	  assert.deepEqual(v.suspendAt, at(30));
200	});
201	
202	test("days past expiry is whole days, and never invents a date without an expiry", () => {
203	  const v = dunningView(
204	    { expiresAt: EXPIRY, dunningStage: 0, dunningNextAt: null },
205	    { ...CFG, hasCard: true, now: at(5.75) },
206	  );
207	  assert.equal(v.daysPastExpiry, 5);
208	
209	  const none = dunningView(
210	    { expiresAt: null, dunningStage: 0, dunningNextAt: null },
211	    { ...CFG, hasCard: true },
212	  );
213	  assert.equal(none.suspendAt, null);
214	  assert.equal(none.daysPastExpiry, 0);
215	});
