53	  return (
54	    <div className="card">
55	      <h2 className="mb-3 font-semibold">Subscription</h2>
56	      {error && (
57	        <div className="mb-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
58	          {error}
59	        </div>
60	      )}
61	      <dl className="space-y-2 text-sm">
62	        <div className="flex justify-between">
63	          <dt className="text-slate-400">Price</dt>
64	          <dd>${(totalMonthlyCents / 100).toFixed(2)}/mo</dd>
65	        </div>
66	        {extraDiskMonthlyCents > 0 && (
67	          <div className="flex justify-between text-xs text-slate-500">
68	            <dt>
69	              incl. {extraDiskGB} GB added storage <span className="text-slate-600">(permanent)</span>
70	            </dt>
71	            <dd>${(extraDiskMonthlyCents / 100).toFixed(2)}/mo</dd>
72	          </div>
73	        )}
74	        <div className="flex justify-between">
75	          <dt className="text-slate-400">Paid until</dt>
76	          <dd>{expiresAt ? expiresAt.slice(0, 10) : "—"}</dd>
77	        </div>
78	        <div className="flex items-center justify-between">
79	          <dt className="text-slate-400">Auto-renew</dt>
80	          <dd>
81	            <button
82	              className={autoRenew ? "btn-secondary py-1" : "btn-primary py-1"}
83	              disabled={pending}
84	              onClick={() => start(() => toggleAutoRenew(serverId))}
85	            >
86	              {autoRenew ? "On — turn off" : "Off — turn on"}
87	            </button>
88	          </dd>
89	        </div>
90	      </dl>
91	      <button
92	        className="btn-primary mt-4 w-full"
93	        disabled={pending}
94	        onClick={() => {
95	          // An irreversible wallet debit gets one confirmation stating the real
96	          // amount and the real duration. There was none, and the label was
97	          // wrong by an order of magnitude — see the prop docs above.
98	          const ok = window.confirm(
99	            suspendedUnpaid
100	              ? `Pay $${(renewTotalCents / 100).toFixed(2)} now to restore this server and extend it by ${renewDurationLabel}?`
101	              : `Renew this server for ${renewDurationLabel}?\n\n$${(renewTotalCents / 100).toFixed(2)} will be taken from your wallet now.`
102	          );
103	          if (!ok) return;
104	          start(async () => {
105	            setError(null);
106	            const res = await renewNow(serverId);
107	            if (res?.error) setError(res.error);
108	          });
109	        }}
110	      >
111	        {pending
112	          ? "Working…"
113	          : suspendedUnpaid
114	            ? `Pay $${(renewTotalCents / 100).toFixed(2)} & restore server`
115	            : `Renew now (+${renewDurationLabel}, $${(renewTotalCents / 100).toFixed(2)})`}
116	      </button>
117	    </div>
118	  );
119	}
