// Opening the bell marks everything read server-side, but `notifications` is a
// prop rendered from the initial server load, so without this the blue count
// and the bold titles would stay lit for the rest of the session even though
// the server now considers them read — a "you have unread mail" badge that
// won't clear. Track the open-and-marked edge locally and reconcile the view
// to it. Once marked, unread is 0 and nothing renders as unread.
const [notifMarked, setNotifMarked] = useState(false);
const unread = notifMarked ? 0 : notifications.filter((n) => !n.readAt).length;

// Escape closes the notifications dropdown too (it only closed the drawer
// before), matching the palette and drawer. A click anywhere else dismisses it
// via the click-away layer rendered below.
useEffect(() => {
  if (!notifOpen) return;
  const onKey = (e: KeyboardEvent) => {
    if (e.key === "Escape") setNotifOpen(false);
  };
  window.addEventListener("keydown", onKey);
  return () => window.removeEventListener("keydown", onKey);
}, [notifOpen]);

