17	export function CommandPalette({ nav }: { nav: NavEntry[] }) {
18	  const [open, setOpen] = useState(false);
19	  const [q, setQ] = useState("");
20	  const [results, setResults] = useState<Result[]>([]);
21	  const [active, setActive] = useState(0);
22	  const router = useRouter();
23	  const inputRef = useRef<HTMLInputElement>(null);
24	  const debounce = useRef<ReturnType<typeof setTimeout> | null>(null);
25	
26	  useEffect(() => {
27	    const onKey = (e: KeyboardEvent) => {
28	      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
29	        e.preventDefault();
30	        setOpen((v) => !v);
31	      }
32	      if (e.key === "Escape") setOpen(false);
33	    };
34	    window.addEventListener("keydown", onKey);
35	    return () => window.removeEventListener("keydown", onKey);
36	  }, []);
37	
38	  useEffect(() => {
39	    if (open) {
40	      setQ("");
41	      setResults([]);
42	      setActive(0);
43	      setTimeout(() => inputRef.current?.focus(), 30);
44	    }
45	  }, [open]);
46	
47	  const navMatches: Result[] = q.length > 0
48	    ? nav
49	        .filter((n) => n.label.toLowerCase().includes(q.toLowerCase()))
50	        .slice(0, 5)
51	        .map((n) => ({ type: "page", label: n.label, sub: n.section, href: n.href }))
52	    : nav.slice(0, 7).map((n) => ({ type: "page", label: n.label, sub: n.section, href: n.href }));
53	
54	  useEffect(() => {
55	    if (debounce.current) clearTimeout(debounce.current);
56	    if (q.length < 2) {
57	      setResults([]);
58	      return;
59	    }
60	    debounce.current = setTimeout(async () => {
61	      try {
62	        const res = await fetch(`/api/search?q=${encodeURIComponent(q)}`);
63	        const json = await res.json();
64	        setResults(json.results ?? []);
65	      } catch {
66	        setResults([]);
67	      }
68	    }, 180);
69	  }, [q]);
70	
71	  const all = [...navMatches, ...results];
72	
73	  const go = useCallback(
74	    (href: string) => {
75	      setOpen(false);
76	      router.push(href);
77	    },
78	    [router]
79	  );
80	
81	  if (!open) return null;
82	
83	  return (
84	    <div
85	      className="fixed inset-0 z-50 flex items-start justify-center bg-black/60 p-4 pt-[12vh] backdrop-blur-sm"
86	      onClick={() => setOpen(false)}
87	    >
88	      <div
89	        className="glass w-full max-w-xl overflow-hidden shadow-2xl animate-fade-up"
90	        onClick={(e) => e.stopPropagation()}
91	      >
92	        <div className="flex items-center gap-3 border-b border-white/[0.08] px-4 py-3">
93	          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#64748b" strokeWidth="2">
94	            <circle cx="11" cy="11" r="7" />
95	            <path d="M21 21l-4-4" />
96	          </svg>
97	          <input
98	            ref={inputRef}
99	            className="w-full bg-transparent text-sm outline-none placeholder:text-slate-500"
100	            placeholder="Search servers, domains, tickets, pages…"
101	            value={q}
102	            onChange={(e) => {
103	              setQ(e.target.value);
104	              setActive(0);
105	            }}
106	            onKeyDown={(e) => {
107	              if (e.key === "ArrowDown") {
108	                e.preventDefault();
109	                setActive((a) => Math.min(a + 1, all.length - 1));
110	              }
111	              if (e.key === "ArrowUp") {
112	                e.preventDefault();
113	                setActive((a) => Math.max(a - 1, 0));
114	              }
115	              if (e.key === "Enter" && all[active]) go(all[active].href);
116	            }}
117	          />
118	          <span className="kbd">esc</span>
119	        </div>
120	        <div className="max-h-[50vh] overflow-y-auto p-2">
121	          {all.length === 0 ? (
122	            <p className="px-3 py-6 text-center text-sm text-slate-500">No results.</p>
123	          ) : (
124	            all.map((r, i) => (
125	              <button
126	                key={`${r.type}-${r.href}-${i}`}
127	                className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm transition-colors ${
128	                  i === active ? "bg-brand-500/20 text-white" : "text-slate-300 hover:bg-white/[0.05]"
129	                }`}
130	                onMouseEnter={() => setActive(i)}
131	                onClick={() => go(r.href)}
132	              >
133	                <span className="w-5 text-center text-xs opacity-70">{typeIcons[r.type] ?? "→"}</span>
134	                <span className="flex-1 truncate">{r.label}</span>
135	                {r.sub && <span className="truncate text-xs text-slate-500">{r.sub}</span>}
136	              </button>
137	            ))
138	          )}
139	        </div>
140	      </div>
141	    </div>
142	  );
143	}
