import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripComments, stripCommentsAndStrings } from "./_source-tools.ts";

/**
 * Structural tripwires for the 2026-07-27 customer-portal audit.
 *
 * Every assertion guards a defect a paying customer actually hit, in one of the
 * four classes this codebase keeps shipping: an uncontrolled field wiped on a
 * rejected submit, a displayed price the server doesn't charge, a success
 * reported before it was verified, and a dead end.
 *
 * `code()` blanks the CONTENTS of comments and string literals (keeping code
 * shape), so an assertion that a CALL or a value-binding is PRESENT can't be
 * satisfied by the same words sitting in a comment or in error copy — this repo
 * is full of incident notes that quote the very code being checked. `lit()`
 * keeps string literals (for asserting an href, a class token or a title).
 */
const REPO = join(__dirname, "..");
const read = (rel: string) => readFileSync(join(REPO, rel), "utf8");
const code = (rel: string) => stripCommentsAndStrings(read(rel));
const lit = (rel: string) => stripComments(read(rel));

/* ---- Class 1: uncontrolled inputs in <form action={fn}> ------------------ */

test("port-forward inputs are controlled — a rejected add keeps the typed port", () => {
  const c = code("components/customer/NetworkingControls.tsx");
  assert.match(c, /value=\{guestPort\}/, "guestPort must be controlled or React 19 blanks it on a rejected submit");
  assert.match(c, /value=\{protocol\}/, "protocol must be controlled");
});

test("DNS record Name and Value are controlled — a rejected add keeps a pasted TXT value", () => {
  const c = code("components/customer/DomainControls.tsx");
  assert.match(c, /value=\{name\}/, "the record name must survive a rejected addDnsRecord");
  assert.match(c, /value=\{address\}/, "the record value (a DKIM/SPF string) must survive a rejected addDnsRecord");
});

test("the demo top-up amount is controlled, never an uncontrolled defaultValue", () => {
  const c = code("components/customer/AddFunds.tsx");
  assert.doesNotMatch(c, /defaultValue=\{/, "an uncontrolled defaultValue snaps back on a rejected topUp");
});

test("the change-password fields are controlled — a wrong current keeps the new password", () => {
  const c = code("components/customer/SettingsForms.tsx");
  assert.match(c, /value=\{current\}/, "current password must be controlled");
  assert.match(c, /value=\{next\}/, "the new password must survive a 'current password is incorrect' rejection");
});

/* ---- Class 2: displayed == charged --------------------------------------- */

test("the subscription card is priced through renewQuote, not raw local math", () => {
  const c = code("app/dashboard/servers/[id]/page.tsx");
  // A game server's monthly run-rate must come from the shared quote, not the
  // base VPS plan.priceCents it is built on ($8.99 shown beside a $4.99 renewal).
  assert.match(c, /renewQuote\.totalCents \/ renewQuote\.months/, "game monthly must derive from renewQuote");
  // Extra disk must go through the shared helper, never a bare multiply.
  assert.match(c, /extraDiskCentsAt\(server\.extraDiskGB/, "extra-disk price must use the shared helper");
  assert.doesNotMatch(
    c,
    /server\.extraDiskGB \* extraDiskPriceCents/,
    "extra-disk price must not be re-derived by local multiplication",
  );
});

/* ---- Class 3: unverified success / honesty ------------------------------- */

test("the mail list is restored (re-fetched) when an archive/delete/move is rejected", () => {
  const c = code("components/customer/mail/MailClient.tsx");
  const restores = c.match(/loadList\(selected, page, search\)/g) ?? [];
  assert.ok(
    restores.length >= 4,
    `each optimistic archive/delete(trash)/delete(hard)/move must reload on failure; found ${restores.length}`,
  );
});

test("a cpanel database is not called 'created' while it is still PENDING", () => {
  const l = lit("components/customer/cpanel/DatabasesPanel.tsx");
  assert.doesNotMatch(l, /database created/, "the SecretCard claimed success before provisioning confirmed");
});

test("the deploy wizard never renders a root-password field it silently discards", () => {
  // Provisioning ALWAYS generates the root password (worker/index.ts); there is
  // no path that reads a customer value, so a field for it is discarded input.
  const c = code("components/customer/DeployWizard.tsx");
  assert.doesNotMatch(c, /rootPw/, "a root-password field here is never submitted and never honoured");
  const l = lit("components/customer/DeployWizard.tsx");
  assert.doesNotMatch(l, /auto-generated if blank/, "copy promising a typed password would be used is a lie");
});

/* ---- Class 4: dead ends --------------------------------------------------- */

test("the SSL 'no running server' hint links out to deploy one", () => {
  const l = lit("components/customer/SslCertificates.tsx");
  assert.match(l, /\/dashboard\/deploy/, "the dead-end must offer a way to deploy a server");
});

test("the calendar page tells a CalDAV outage apart from an empty account", () => {
  const c = code("app/dashboard/calendar/page.tsx");
  assert.match(c, /if \(failed\)/, "an outage must branch separately from calendars.length === 0");
  assert.doesNotMatch(c, /if \(failed \|\| calendars\.length/, "outage and empty must not share one screen");
  const l = lit("app/dashboard/calendar/page.tsx");
  assert.match(l, /Couldn't reach your calendar/, "an outage must not read as 'no calendar connected'");
});

test("a calendar task can't be deleted by one stray click", () => {
  const c = code("components/customer/calendar/TaskPanel.tsx");
  assert.match(c, /window\.confirm\(/, "task delete must confirm — it is immediate with no undo");
  assert.match(c, /onDelete\(task\.id\)/);
});

test("the empty games page offers a support link, not a dead 'contact support'", () => {
  const l = lit("app/dashboard/games/page.tsx");
  assert.match(l, /\/dashboard\/support/, "'contact support' must be an actual link");
  const c = code("app/dashboard/games/page.tsx");
  assert.match(c, /action=\{/, "the EmptyState must carry an action");
});

/* ---- Portal shell: a11y + dead ends -------------------------------------- */

test("the notifications bell is labelled and exposes its open state", () => {
  const c = code("components/portal/Shell.tsx");
  assert.match(c, /aria-expanded=\{notifOpen\}/, "the icon-only bell must announce as more than 'button'");
});

test("a notification with no target is not a link to a dead '#' anchor", () => {
  const c = code("components/portal/Shell.tsx");
  assert.doesNotMatch(c, /n\.href \?\? /, "a hrefless notification must render as a plain row, not href='#'");
});

test("the notifications dropdown is dismissable and clears its badge optimistically", () => {
  const c = code("components/portal/Shell.tsx");
  assert.match(c, /notifMarked/, "opening the bell must clear the unread badge in the client, not just server-side");
  assert.match(c, /if \(!notifOpen\) return;/, "a dedicated Escape/click-away path for the dropdown");
  const l = lit("components/portal/Shell.tsx");
  assert.match(l, /Close notifications/, "the click-away layer must be labelled");
});

test("the command palette is an accessible dialog that restores focus on close", () => {
  const l = lit("components/portal/CommandPalette.tsx");
  assert.match(l, /role="dialog"/);
  assert.match(l, /aria-modal/);
  const c = code("components/portal/CommandPalette.tsx");
  assert.match(c, /restoreFocus/, "focus must return to the trigger, not drop to the document top");
});

/* ---- Domain toggle switches: state announced to assistive tech ----------- */

test("domain toggle switches announce role and state", () => {
  for (const f of [
    "components/customer/DomainControls.tsx",
    "components/customer/DomainAdvanced.tsx",
    "components/customer/DomainRedirects.tsx",
  ]) {
    assert.match(lit(f), /role="switch"/, `${f} toggle missing role=switch`);
    assert.match(code(f), /aria-checked=\{/, `${f} toggle missing aria-checked`);
  }
});

