// Proves each audit tripwire BITES: apply the exact pre-fix text to the current
// source in memory, and confirm the assertion that passes now would FAIL.
import { readFileSync } from "node:fs";
import { execSync } from "node:child_process";

const REPO = "/opt/nxeon";
const read = (rel) => readFileSync(`${REPO}/${rel}`, "utf8");

// Reuse the repo's real strippers so the proof matches the test exactly.
const tools = execSync(
  `cd ${REPO} && npx tsx -e "import {stripComments,stripCommentsAndStrings} from './test/_source-tools.ts'; ` +
    `globalThis.out=(s)=>process.stdout.write(JSON.stringify(s)); ` +
    `import('node:fs');"`,
).toString();
// Simpler: shell out per-check is slow. Import via dynamic tsx loader instead.

// Throwaway proof (NOT a *.test.ts, so `npm test` ignores it): for every audit
// tripwire, apply the EXACT pre-fix text to the current source in memory and
// confirm the assertion flips from pass → fail. Run: npx tsx test/_prove-bites.mts
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { stripComments, stripCommentsAndStrings } from "./_source-tools.ts";

const REPO = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = (rel: string) => readFileSync(join(REPO, rel), "utf8");
const code = (s: string) => stripCommentsAndStrings(s);
const lit = (s: string) => stripComments(s);

let ok = 0;
let bad = 0;
/** Assert the tripwire holds on current src, and FAILS on the reverted src. */
function prove(
  name: string,
  rel: string,
  revert: (src: string) => string,
  holds: (processed: string) => boolean,
  strip: (s: string) => string = code,
) {
  const cur = read(rel);
  const passesNow = holds(strip(cur));
  const failsReverted = !holds(strip(revert(cur)));
  const good = passesNow && failsReverted;
  if (good) ok++;
  else bad++;
  console.log(
    `${good ? "BITES  " : "WEAK ! "} ${name}` +
      (good ? "" : `  (passesNow=${passesNow} failsReverted=${failsReverted})`),
  );
}

